@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-4 p-4 bg-primary text-white rounded">
    <h1 class="display-5">University Course Catalog</h1>
    <p class="lead mb-3">Explore our departments and courses for the upcoming semester.</p>
    <a href="/courses" class="btn btn-light btn-lg">Browse All Courses</a>
</div>

<h2 class="mb-3">Featured Courses</h2>
<div class="row mb-5">
    @foreach (var course in featuredCourses)
    {
        var dept = Catalog.GetDepartment(course.DepartmentId);
        <div class="col-md-6 col-lg-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.Code</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
