@inject CatalogService Catalog
@inject NavigationManager Navigation

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>
<p class="text-muted">Fill out the form below to request enrollment in a course. All fields marked with * are required.</p>

<div class="row">
    <div class="col-lg-8">
        <EditForm Model="request" FormName="enrollment" OnValidSubmit="HandleSubmit" method="post">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger mb-3" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name *</label>
                <InputText id="studentName" @bind-Value="request.StudentName" class="form-control" />
                <ValidationMessage For="() => request.StudentName" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID *</label>
                <InputText id="studentId" @bind-Value="request.StudentId" class="form-control" placeholder="e.g. STU-12345" />
                <ValidationMessage For="() => request.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course *</label>
                <InputSelect id="courseId" @bind-Value="request.CourseId" class="form-select">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => request.CourseId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="comments" class="form-label">Comments</label>
                <InputTextArea id="comments" @bind-Value="request.Comments" class="form-control" rows="3" />
                <ValidationMessage For="() => request.Comments" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Request</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest request { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> courses = new();

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();
        if (CourseId.HasValue && request.CourseId == 0)
        {
            request.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        Catalog.SubmitEnrollment(request);
        var courseName = Catalog.GetCourse(request.CourseId)?.Title ?? "the selected course";
        Navigation.NavigateTo($"/enroll/confirmation?courseName={Uri.EscapeDataString(courseName)}&studentName={Uri.EscapeDataString(request.StudentName)}");
    }
}
